    ctx['result'] = draft.strip()

evaluation.code:
def evaluate(task_input, result):
    ok = isinstance(result, str) and len(result.strip()) >= 40
    notes = 'reply present and substantive' if ok else 'reply missing or too short'
    return {'passed': ok, 'score': 1.0 if ok else 0.0, 'notes': notes}
